		[14311]={[1]={1533,53.5,80.4,nil,nil,339601,"Take the |cFFFFFFFFPurian|r from the bench at |cFFFFFFFF54.3, 81.8|r, place them in the tribute bowls at |cFFFFFFFF54.4, 83.8|r and |cFFFFFFFF56.1, 83.0|r, and follow the light to the treasure at |cFF"},[2]={1533,58.6,71.4,nil,nil,352428},[3]={1533,52,86,nil,nil,339641},[4]={1533,59.3,60.9,nil,nil,354213},[5]={1533,55.7,42.8,nil,nil,354214,"At the back of the cave."},[6]={1533,40.5,49.8,nil,nil,354208},[7]={1533,46.4,46.5,nil,nil,354202,"Coordinates are for a cave entrance hidden by plants."},[8]={1533,51.5,18,nil,nil,354275,"Requires an |cFFFFFFFFUnstable Construct Anima|r, which can be found in the surrounding area. It looks similar to the other jars of anima, but is smaller and glows purple."},[9]={1533,35.8,48.1,nil,nil,354289,"The |cff0070ddBroken Kyrian Flute|r drops from |cFFFFFFFFEtherwyrms|r across Bastion.\nAlthough they do drop from |cFFFFFFFFUnsettled Etherwyrms|r near the treasure, the best place to farm the flute is"},[10]={1533,56.5,17.2,nil,nil,355286,"Purchase |cFFFFFFFFMemorial Wine|r from Kobri, a steward at Hero's Rest. Place the wine in the Drink Tray at |cFFFFFFFF56.8, 19.0|r to get the key from Honor Steward to the Memorial Offerings chest."},[11]={1533,39.1,54.4,nil,nil,353942,"The coordinates are to the first object you need to click to unlock the chest, |cFFFFFFFFAgthia's Flame|r.\n\nRun south until you get to the second torch at |cFFFFFFFF38.4, 57.0|r and click it. An invis"},[12]={1533,64.8,71.1,nil,nil,353940,"Ring one of the Bells of Purification on either side of the treasure. Then turn around and stand in the waterfall next to the Purity Steward. You will get a buff called Proof of Purity, allowing you t"},[13]={1533,70.4,36.4,nil,nil,353941,"Kneel in front of the chest."},[14]={1533,40.6,18.9,nil,nil,353943,"Requires taking multiple transport pads on the |cFFFFFFFFPath of Wisdom|r and clicking on objects in the correct order.\n\n1. Incense of Patience\n2. Incense of Knowledge\n3. Incense of Insight\n4. Blue or"},[15]={1533,27.6,21.8,nil,nil,353944}},
		[14312]={[1]={1536,47.2,62.1,nil,nil,347444},[3]={1536,30.7,28.7,nil,nil,353380},[4]={1536,59.8,79,nil,nil,355865,"Pick up the |cFFFFFFFFEmpty Plague Bottle|r from the table next to the vat."},[5]={1536,65.6,50.8,nil,nil,355872,"There are two caves - the treasure is in the lower one."},[6]={1536,42.3,23.3,nil,nil,355880},[7]={1536,22.5,30.5,nil,nil,341424,"Unlock the gate to the treasure by clicking the chain at |cFFFFFFFF25.8, 53.9|r.\n\nThe treasure will respawn about 5 minutes after being looted by another player."},[8]={1536,48.3,16.3,nil,nil,345456,"The path to the treasure starts at |cFFFFFFFF51.6, 13.7|r. Climb up the side of the crumbled building until you get close to the treasure, then turn right and walk up the cliff to it."},[9]={1536,62.4,59.9,nil,nil,351980,"On top of the mushroom."},[10]={1536,72.1,52.7,nil,nil,355947,"In a cave behind the slime waterfall."},[11]={1536,31.7,70,nil,nil,356535,"You need |cFFFFFFFFPhaeton's Key|r from Runespeaker Phaeton at |cFFFFFFFF37.8, 70.1|r to open the chest. "},[12]={1536,57.7,75.9,nil,nil,355886,"To access this chest, you need the |cFFFFFFFFPlaguefallen|r debuff. You can either pick up a Plaguefallen Potion from |cFFFFFFFF58.4, 73.3|r in Plague Watch, or stand in green slime until you have 10 "},[13]={1536,64.7,24.7,nil,nil,355980,"Loot the |cFFFFFFFFRitual Pages|r from the front-right corner of the room. Take them to the back-right corner and use the |cFFFFFFFFBook of Binding Rituals|r, and then you can loot the chest."}},
		[14313]={[1]={1565,55.9,21,171156,nil},[2]={1565,48.2,20.3,nil,nil},[3]={1565,52.9,37.2,nil,nil,354646,"The path to get up to the treasure starts at |cFFFFFFFF50.6, 38.8|r."},[4]={1565,76.6,29.7,nil,nil},[5]={1565,49.7,55.9,nil,nil,354652,"Underneath the platform."},[6]={1565,67.8,34.6,nil,nil,355355,"You need two people to open the chest. One person needs to play the harp and one needs to play the drums."},[7]={1565,48.2,39.2,nil,nil,354647,"The path to get up to the treasure starts at |cFFFFFFFF48.1, 39.0|r.\n\nFollow it up and to the left until you reach the beginning of the bridge at |cFFFFFFFF46.1, 39.1|r, and cross it to get to the led"},[9]={1565,63.8,37.5,nil,nil,355041,"Combine the |cff1eff00Diary of the Night|r, |cff1eff00Gardener's Basket|r, |cff1eff00Gardener's Hammer|r, |cff1eff00Gardener's Flute|r, and |cff1eff00Gardener's Wand|r to create |cff0070ddTwinklestar'"},[10]={1565,31.7,32.5,171484,nil,nil,"Collect Aromatic Flowers from |cFFFFFFFF31.7, 32.5|r, jump onto the tree with the Bounding Shroom at |cFFFFFFFF41.4, 31.6|r, and burn the flowers."},[11]={1565,37.6,37,nil,nil,354650,"Use the Bounding Shroom at |cFFFFFFFF38.0, 36.2|r to get to the top of the tree."},[12]={1565,36.4,25,nil,nil},[13]={1565,44.8,75.8,nil,nil,354662,"Use the Lamp at |cFFFFFFFF46.4, 70.1|r and open the chest while you have the debuff."},[14]={1565,36.1,65.2,nil,nil,355000,"You need to dispel the barrier with |cff0070ddFae Dreamcatcher|r, which you create by combining |cff1eff00Enchanted Bough|r, and |cff1eff00Fae Ornament|r, and |cff1eff00Raw Dream Fibers|r."},[15]={1565,36.1,65.2,nil,nil,354648,"Use the Mushroom at |cFFFFFFFF37.6, 61.5|r and jump into the broken tree.\n\nThis treasure has a chance to contain any of the BoEs that can drop from Decayed Husks and Hunter Vivanna."}},
		[14314]={[1]={1525,37.7,69.2,nil,nil,357467,"Take the |cFFFFFFFF[Forbidden Ink]|r from the library at |cFFFFFFFF37.6, 68.7|r and give it to the Lost Quill."},[2]={1525,38.4,44.2,nil,nil,357487,"Go up the stairs that start at 41.3, 44.9."},[3]={1525,57.3,43.3,173488,nil},[4]={1525,80,37.1,nil,nil,357572},[5]={1525,70.1,60,nil,nil,357584},[6]={1525,29.6,37.1,nil,nil,357683},[7]={1525,62.8,75.3,nil,nil,357697,"Use the Ingress And Egress Rites at |cFFFFFFFF63.0, 72.1|r to see the Chest."},[8]={1525,47.3,55.3,nil,nil,358298,"Use the Anima Canister to drain anima from Silent Observers, and then use the Extra Action Button next to the Chamber Guardian."},[9]={1525,31.1,55,nil,nil,349798},[10]={1525,69.3,77.9,nil,nil,349565},[11]={1525,64.2,72.7,nil,nil,349792},[12]={1525,68.4,64.4,nil,nil,349793,"Use the nearby Bounding Shroom to get up to the treasure."},[13]={1525,61.5,58.6,nil,nil,349794,"Hug the cliff from the nearby flight path around the building.\nDrops 2 random green zone drops."},[14]={1525,46.4,58.1,nil,nil,349795,"Use the Bounding Shroom at 47.0, 58.3 to reach the treasure."},[15]={1525,75.2,56.1,nil,nil,349796,"There is a Greedy Soul that wanders up and down the road. Kill it, and it will drop the treasure."},[16]={1525,51.8,59.5,nil,nil,349797,"You can reach it with Door of Shadows or by jumping down from the road above."}},
