		[15331]={[1]={1970,58.9,77,nil,nil,373543,"There are tablets around the Cave. The correct one is located in the back at 57.9 78.9."},[2]={1970,58.8,73.1,nil,nil,369757,"Bring Orb at 59,4, 76,8 to the pump."},[3]={1970,38.2,37.2,nil,nil,370140,"Jumping puzzle."},[4]={1970,51.6,86.6,nil,nil,373548,"Found inside of Nexus of Actualization. Push Orb in the room before"},[5]={1970,67,69.4,nil,nil,373561,"This chest only spawn during WQ Frog'it (65089)."},[6]={1970,52.7,63,nil,nil,374976,"The Broken Automa next to chest will give you sound cues, press the remaining 4 Broken Consoles in the correct order. With your back against the entrance:\nTOP RIGHT\nDOWN LEFT\nDOWN RIGHT\nTOP LEFT."},[7]={1970,60.6,30.8,nil,nil,375272},[8]={1970,37.9,65.2,nil,nil,375281,"Jumping Puzzle."},[9]={1970,51.6,9.9,nil,nil,375376,"Use the Forgotten Translocator nearby to teleport up."},[10]={1970,39,73.2,nil,nil,375369,"Jumping Puzzle, Start on the top of the nearby vault. On the big rock."},[11]={1970,60,18,nil,nil,375354,"The mob Mawsworn Inquisitor has a 1-2% drop chance for the key."},[12]={1970,49.8,87.3,nil,nil,375405,"Jumping Puzzle, on top of the tree ring."},[13]={1970,61.2,37.2,nil,nil,375408,"Only available after unlocking Protoform Synthesis: Mount."},[14]={1970,56.8,64.2,nil,nil,375382,"To open it you need to pick up a Jiro Hammer(189768). On top of the rock there is a repair tool that you can use to trade with the nearby Jiros(Hiu Fi 185151) for a Jiro Hammer."},[15]={1970,35.2,44.1,nil,nil,375422,"Jump from the ledge above the flight path to the rock."},[16]={1970,53.6,72.2,nil,nil,375411,"Inside the cave. Need to collect 5xLost Ovoids around Zereth Mortis."},[17]={1970,34.8,69.9,nil,nil,375413,"Need to have completed Dealic Understanding. At 34.5, 70.5 there is a Coreless Aurelid(185282), use Popopoc on it to get the chest."},[18]={1970,34.8,56.1,nil,nil,375423},[19]={1970,46.6,31,nil,nil,375478,"Use the cosmic system to get to the top and use some form of glide/teleport/flying."},[20]={1970,60.8,42.9,nil,nil,375481,"You need flying/teleport to get here, on top of the pillar."},[21]={1970,34,67.6,nil,nil,375483,"Jumping Puzzle, climb on top of the slumbering vault in Haven."},[22]={1970,37.2,78.2,nil,nil,375484,"Pet all the creatures in the area. The creature will sit down after being petted. The Jiro will yell when you are done."},[23]={1970,52.8,71.4,nil,nil,375485,"Jumping Puzzle. Go around to get on top of the rock behind the treasure and jump down."},[24]={1970,76.8,46.6,nil,nil,375492,"Inside a cave. Now you need to touch 6 glowing things on columns with symbols all over the island. Each action give buff. Need to stack 6 (touch same amount of pylons) times and then touch glowing thi"},[25]={2027,65.4,47.1,nil,nil,375493,"Available inside the Blooming Foundry (63.2, 73.1) during Glimmercanes Questline (Need Sopranian Understanding). You need to collect 5 Pollen Cloud buffs (Green Clouds)."},[26]={1970,52,80,nil,nil,375495,"There is four runes that needs to be activated to activate the teleporter."},[27]={1970,47.5,95.2,nil,nil,375496,"Kill Nascent Servitor(182368) until you have 5 buffs then you can open the door."}},
