		[20001]={[1]={554,43.1,41.2,72769,nil},[2]={554,60.6,87.8,72048,nil},[3]={554,44,70,73854,nil,nil,"Locate the bloodied red crane corpse, Fishgorged Crane at ~44, 70. If it's not present, then the rare can't be spawned yet.\n\nIf the corpse is there, head south and aggro one of the Fishgorged Cranes b"},[4]={554,59.5,48.9,71864,nil,nil,"Use the Cloudstrike ability from the Cloudstrike Family Helm to break down the caved in rocks. If you AFK inside the cave or Mage Blink / Warrior Leap through the rocks, you can interact with the Rock"},[5]={554,25.2,35.8,72045,nil,nil,"Click on Conspicuously Empty Shell to spawn Chelon."},[6]={554,33.8,85.8,72193,nil},[7]={554,37.8,77.2,71919,nil,nil,"Kill 10 Skunky Brew Alementals to spawn Zhu-gon the Sour in the town when the event is active."},[8]={554,30.2,71.6,72909,nil},[9]={554,47,87.4,72245,nil},[10]={554,36.4,46.3,73158,nil,nil,"Travel around the area where the Celestial bosses spawn and kill Brilliant Windfeathers — whenever one respawns, there's a chance it will respawn as an Emerald Gander instead of the normal mob."},[11]={554,20.6,43.2,73161,nil,nil,"Travel along the beach and kill Great Turtles — whenever one respawns, there's a chance it will respawn as a Great Turtle Furyshell instead of the normal mob."},[12]={554,67.2,44,73277,nil},[13]={554,29.6,45.8,73160,nil,nil,"Travel around the area where the Celestial bosses spawn and kill Ironfur Great Bulls — whenever one respawns, there's a chance it will respawn as an Ironfur Steelhorn instead of the normal mob."}},
		[20002]={[1]={554,43.1,41.2,73157,nil},[2]={554,54.1,52.9,73175,nil},[3]={554,71.2,82.6,73704,nil},[4]={554,64.6,28.6,73282,nil},[5]={554,54.2,42.8,72808,nil},[6]={554,66,58.8,73167,nil,nil,"Huolon spawns around the coordinate we have listed, but if he's not pulled immediately he will fly up the hill, over the first upper bridge, and loop back down."},[7]={554,16.2,60.6,73166,nil,nil,"Travel along the beach and kill Ancient Spineclaws — whenever one respawns, there's a chance it will respawn as a Monstrous Spineclaw instead of the normal mob."},[8]={554,62.1,77.1,72775,nil},[9]={554,26.5,27.8,73281,nil,nil,"You need to have a Mist-Filled Spirit Lantern from Evermaw to summon this boss when the Cursed Gravestone is active."},[10]={554,62.2,63.2,72970,nil},[11]={554,25.8,46.6,73163,nil,nil,"Travel around the zone and kill Death Adders — whenever one respawns, there's a chance it will respawn as an Imperial Python instead of the normal mob."},[13]={554,48.4,33.3,73174,nil},[14]={554,57.6,76.6,73170,nil},[15]={554,43.6,26,73173,nil},[16]={554,53,82.4,73169,nil},[17]={554,40.6,27.2,73172,nil},[18]={554,60.6,48.4,73171,nil,nil,"This rare patrols all the way down the pathway from the upper bridge to the lower one."}},
