		[40828]={[1]={2255,34,61,nil,nil,446419},[2]={2256,62.7,87.9,nil,nil,446404,"Interact with Black Blood Extractors in area or stand in Black Blood pools until you reach at least 50 Unseeming Shift debuff to see Corrupted Memory near the cache. Kill it to obtain key for cache."},[3]={2255,78.6,33.2,nil,nil,446420,"Collect colored Silk Scrap from the nearby platform in order to open the treasure chest."},[4]={2213,67.4,74.4,nil,nil,446421,"IT'S A TRAP! Navigate through the web traps to get to the treasure."},[5]={2255,49.5,43.7,nil,nil,446423,"Above on a web, near the ceiling."},[6]={2255,67.4,90.7,nil,nil,446097},[7]={2255,67.5,27.5,nil,nil,446299},[8]={2213,31.6,20.7,nil,nil,446101,"Below the terrace, hanging from the ceiling."},[9]={2255,54.5,50.8,nil,nil,446135,"Below, hanging from a bridge."},[10]={2255,38.8,37.2,nil,nil,446140}},
		[40848]={[2]={2215,55.1,51.9,nil,nil,453283,"Fly down to the Dead Arathi body and loot key."},[3]={2215,59.5,59.7,nil,nil,453374,"Inside the cave. Interact with the book and start the ritual. Survive the attack and kill the shadows."},[4]={2215,40,51.1,nil,nil,453741},[6]={2215,55.8,69.5,nil,nil,441606,"Located inside the crack of the pillar high above ground."},[7]={2215,30.2,38.8,nil,nil,441611},[8]={2215,50.1,13.8,nil,nil,441638},[9]={2215,45.9,45.1,nil,nil,441800,"You need to talk to Sky-Captains Aerthin, Clairmonte, Dornald, and Onaro on their respective airships."},[10]={2215,58.4,27.2,nil,nil,437211,"Starblessed Glimmerfly flies around in circle casting Lightning Orbs on the ground.\nCatch 5 Lightning Orbs by standing in illuminated circles in order to reveal the treasure."},[11]={2215,76.8,53.8,nil,nil,419695,"Inside the Shadowmire cave."}},
		[40862]={[1]={2255,59,18.6,nil,nil},[2]={2255,78,62.8,nil,nil},[3]={2255,56.9,39,nil,nil},[4]={2255,44.8,66.3,nil,nil},[5]={2213,62,41.4,nil,nil},[6]={2213,49.7,22.3,nil,nil},[7]={2216,57.4,38.5,nil,nil},[8]={2215,69.1,45.7,nil,nil},[9]={2215,40.6,68,nil,nil},[10]={2215,49.1,39.5,nil,nil},[11]={2215,42.8,55.7,nil,nil},[12]={2339,45,47.3,nil,nil},[13]={2248,42,74.4,nil,nil},[14]={2248,58.2,27.1,nil,nil},[15]={2214,55.3,64.1,nil,nil},[16]={2214,43.7,32.1,nil,nil},[17]={2214,59.2,79,nil,nil},[18]={2214,57.7,46.3,nil,nil}},
		[40871]={[1]={71,63.9,52.4,nil,nil,nil,"Speak to Alphonse after having looted the Six of Frost to unlock this quest. Use the Idol of Ohn'ahra to find more cards scattered around the grounds."},[2]={71,63.1,52,nil,nil},[3]={71,61.9,50.5,nil,nil,nil,"Talk to Riko, Shademaster Kiryn, then Sully. Visit Gizmo's grave in the Jade Forest, then chase him down to return to Riko. Wait 5 minutes for Riko to send you mail."},[4]={71,63,50.2,nil,nil,nil,"Open the Lost & Found box nest to Alyx then return the items to visitors around the anniversary grounds."},[5]={71,63,50.2,nil,nil,nil,"Speak to Lashk by the story time stage, locate Nola's Last Wish south of Tortaka Refuge in Vol'Dun, then used it to summon and speak to Scrollsage Nola's spirit at the underwater Tortollan wedding wes"},[6]={36,61.4,28.7,nil,nil,nil,"Summon Voidfire with the provided whistle then talk to him in the following locations:\nNear the Ruins of Thaurissan in the Burning Steppes (61.4, 28.7)\nNear the Scar of the Worldbreaker in the Badland"},[7]={71,64.2,51.3,nil,nil,nil,"Interact with four feathers hidden around Spires of Arak, Shattrath, Nagrand and Frostfire Ridge in Draenor."},[8]={71,62.2,49.7,nil,nil,nil,"Interact with the Jumping Spider in the Bamboo Wilds in Jade Forest and the Summit Kid atop Neverest Pinnacl in Kun'Lai Summit."},[9]={1565,41.5,44.8,nil,nil,nil,"Collect the Mask of the Trickster and the Play Script from on and behind the stage, and the Prop Sword and Conductor's Baton from near the venue entrance."}},
		[40872]={[1]={71,61,50.6,nil,nil,nil,"Speak to Hemet, Leeroy, and Addie to suss out the detectives' stories, then accuse one. Chase the intruder east of Bootlegger Outpost and kill him."},[2]={71,63.2,52.4,nil,nil,nil,"Talk to Maru, suspect a dog, then visit Urban Planner Volrath in Boralus.\nCollect a chew toy from the mountaintop behind Maruukai in the Ohn'ahran plains.\nPlace the Chew Toy in a Toy Box  in Teerakai "},[4]={71,61,50.7,nil,nil,nil,"Speak to the time-displaced visitors, toss letters to eventgoers, speak to Bonenose at the north camp again, then head a bit northeast up the beach to celebrate with Alyx."}},
